import { useState, useEffect } from 'react'
import { ArrowLeft, ArrowRight } from 'lucide-react'
import { GENRES } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import { SeriesCard } from '../components/SeriesCard'
import { navigate } from '../lib/router'
import { cx, genreHref, formatViews, chapterCountOf } from '../lib/utils'
import { setSeo, buildKindMeta } from '../lib/seo'

const PAGE_SIZE = 60

const COPY: Record<'manhwa' | 'manhua', { h1: string; blurb: string; label: string }> = {
  manhwa: {
    // H1 carries the GSC-proven "read manhwa online" head query after the
    // "Browse All" prefix the seo-test suite pins (mirrors prerender.mjs).
    h1: 'Browse All Manhwa — Read Manhwa Online Free',
    blurb:
      'Every Korean manhwa on MANHWAS — full-color webtoons with weekly chapter drops. Follow a series, track your progress, and read from chapter one free.',
    label: 'manhwa',
  },
  manhua: {
    h1: 'Browse All Manhua — Read Manhua Online Free',
    blurb:
      'Every Chinese manhua on MANHWAS — cultivation epics, system rebirths, and long-running epics with full chapter lists, free to read.',
    label: 'manhua',
  },
}

export default function KindHub({ kind }: { kind: 'manhwa' | 'manhua' }) {
  const { series: catalog, loading } = useCatalog()
  const [shown, setShown] = useState(PAGE_SIZE)

  const list = catalog.filter((s) => (kind === 'manhua' ? s.kind === 'manhua' : s.kind !== 'manhua'))

  // Per-kind metadata with the real series count
  useEffect(() => {
    setSeo(buildKindMeta(kind, list.length))
  }, [kind, catalog.length])

  const copy = COPY[kind]
  const otherKind = kind === 'manhwa' ? 'manhua' : 'manhwa'
  const otherCount = catalog.filter((s) =>
    otherKind === 'manhua' ? s.kind === 'manhua' : s.kind !== 'manhua',
  ).length

  const totalChapters = list.reduce((n, s) => n + chapterCountOf(s), 0)
  const ongoing = list.filter((s) => s.status === 'Ongoing').length
  const completed = list.filter((s) => s.status === 'Completed').length

  // Only expose genres that actually contain this kind of series
  const genreCounts = GENRES.map((g) => ({
    genre: g.name,
    count: list.filter((s) => s.genres?.includes(g.name)).length,
  })).filter((x) => x.count > 0)

  const top = [...list].sort((a, b) => b.weeklyViews - a.weeklyViews)

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background:
            kind === 'manhua'
              ? 'linear-gradient(115deg, hsl(280 25% 15%) 0%, hsl(310 22% 26%) 100%)'
              : 'linear-gradient(115deg, hsl(210 30% 14%) 0%, hsl(200 28% 26%) 100%)',
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/catalog')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> All Series
          </button>
          <div className="eyebrow text-accent">Browse by Type</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">{copy.h1}</h1>
          <p className="mt-3 max-w-xl text-white/70">{copy.blurb}</p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : list.length}</strong> series
            </span>
            <span>
              <strong className="text-white">{loading ? '…' : formatViews(totalChapters)}</strong>{' '}
              chapters
            </span>
            <span>
              <strong className="text-white">{loading ? '…' : ongoing}</strong> ongoing
            </span>
            <span>
              <strong className="text-white">{loading ? '…' : completed}</strong> completed
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {/* Genre + status jump links */}
        <div className="mb-8 flex flex-wrap gap-1.5">
          {genreCounts.map(({ genre, count }) => (
            <a
              key={genre}
              href={genreHref(genre)}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(genreHref(genre))
              }}
              className="rounded-full border border-line-strong bg-paper px-3.5 py-1.5 text-xs font-semibold text-ink-soft transition-colors hover:border-ink hover:text-ink"
            >
              {genre} <span className="text-ink-faint">{count}</span>
            </a>
          ))}
        </div>

        <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
          <div className="text-sm text-ink-faint">
            {kind === 'manhua' ? (
              <>
                Top <strong className="text-ink">manhua</strong> this week
              </>
            ) : (
              <>
                Most-followed <strong className="text-ink">manhwa</strong> this week
              </>
            )}
          </div>
          <a
            href="/catalog"
            onClick={(e) => {
              if (e.metaKey || e.ctrlKey) return
              e.preventDefault()
              navigate('/catalog')
            }}
            className="text-sm font-semibold text-accent hover:underline"
          >
            Filter the full catalog →
          </a>
        </div>

        {loading ? (
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {Array.from({ length: 10 }).map((_, i) => (
              <div key={i}>
                <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
                <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              </div>
            ))}
          </div>
        ) : list.length === 0 ? (
          <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
            <div className="text-lg font-bold">No stories found</div>
            <p className="mt-2 text-sm text-ink-soft">No {copy.label} series in the catalog yet.</p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
              {top.slice(0, shown).map((s) => (
                <SeriesCard key={s.id} series={s} />
              ))}
            </div>
            {shown < list.length && (
              <div className="mt-10 text-center">
                <button
                  onClick={() => setShown((n) => n + PAGE_SIZE)}
                  className="inline-flex items-center gap-2 rounded-full border border-ink/25 bg-paper px-5 py-2.5 text-sm font-semibold text-ink transition-all hover:border-ink hover:bg-ink hover:text-paper"
                >
                  Show more
                  <span className="text-ink-faint">
                    {Math.min(PAGE_SIZE, list.length - shown)} of {list.length} left
                  </span>
                </button>
              </div>
            )}
          </>
        )}

        {/* Keep exploring */}
        <section className="mt-16">
          <div className="eyebrow mb-4 text-accent">Keep Exploring</div>
          <div className="grid gap-3 sm:grid-cols-3">
            <a
              href={`/${otherKind}`}
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate(`/${otherKind}`)
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">
                  {otherKind === 'manhua' ? 'Browse All Manhua' : 'Browse All Manhwa'}
                </div>
                <div className="mt-0.5 text-xs text-ink-faint">{otherCount} titles</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
            <a
              href="/status/ongoing"
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate('/status/ongoing')
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">Ongoing Manhwa</div>
                <div className="mt-0.5 text-xs text-ink-faint">New chapters daily</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
            <a
              href="/updates"
              onClick={(e) => {
                if (e.metaKey || e.ctrlKey) return
                e.preventDefault()
                navigate('/updates')
              }}
              className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
            >
              <div>
                <div className="font-extrabold tracking-tight group-hover:text-accent">Latest Updates</div>
                <div className="mt-0.5 text-xs text-ink-faint">Newest chapters</div>
              </div>
              <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
            </a>
          </div>
        </section>
      </div>
    </main>
  )
}
